class Solution:
    def minimumCost(self, target, words, costs):
        INF = float('inf')
        L = len(target)
        dp = [INF] * (L + 1)
        dp[0] = 0
        wc = list(zip(words, costs))
        for i in range(L):
            if dp[i] == INF:
                continue
            for w, c in wc:
                j = i + len(w)
                if j <= L and target.startswith(w, i) and dp[i] + c < dp[j]:
                    dp[j] = dp[i] + c
        return dp[L] if dp[L] < INF else -1

