class Solution:
    def minimumCost(self, target, words, costs):
        INF = float('inf')
        L = len(target)
        best = {}
        for w, c in zip(words, costs):
            if w not in best or c < best[w]:
                best[w] = c
        byLen = {}
        for w, c in best.items():
            byLen.setdefault(len(w), []).append((w, c))
        lens = sorted(byLen, reverse=True)
        dp = [INF] * (L + 1)
        dp[0] = 0
        for i in range(L):
            if dp[i] == INF:
                continue
            for ln in lens:
                j = i + ln
                if j > L:
                    continue
                for w, c in byLen[ln]:
                    if target.startswith(w, i) and dp[i] + c < dp[j]:
                        dp[j] = dp[i] + c
        return dp[L] if dp[L] < INF else -1

