class Solution {
public:
    int minimumCost(string target, vector<string>& words, vector<int>& costs) {
        const int INF = INT_MAX / 2;
        int L = target.size();
        unordered_map<string, int> best;
        for (int i = 0; i < (int)words.size(); i++) {
            auto it = best.find(words[i]);
            if (it == best.end() || costs[i] < it->second) best[words[i]] = costs[i];
        }
        vector<pair<string,int>> ws(best.begin(), best.end());
        vector<int> dp(L + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < L; i++) {
            if (dp[i] >= INF) continue;
            for (auto& [w, c] : ws) {
                int len = w.size();
                if (i + len <= L && target.compare(i, len, w) == 0)
                    dp[i + len] = min(dp[i + len], dp[i] + c);
            }
        }
        return dp[L] >= INF ? -1 : dp[L];
    }
};

