class Solution {
    public int minimumCost(String target, String[] words, int[] costs) {
        final int INF = Integer.MAX_VALUE / 2;
        int L = target.length();
        Map<String, Integer> best = new HashMap<>();
        for (int i = 0; i < words.length; i++)
            best.merge(words[i], costs[i], Math::min);
        List<Map.Entry<String, Integer>> ws = new ArrayList<>(best.entrySet());
        int[] dp = new int[L + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < L; i++) {
            if (dp[i] >= INF) continue;
            for (var e : ws) {
                int len = e.getKey().length();
                if (i + len <= L && target.startsWith(e.getKey(), i))
                    dp[i + len] = Math.min(dp[i + len], dp[i] + e.getValue());
            }
        }
        return dp[L] >= INF ? -1 : dp[L];
    }
}

