    });
    const ws = [...best.entries()];
    const dp = new Array(L + 1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < L; i++) {
        if (dp[i] === INF) continue;
        for (const [w, c] of ws) {
            const len = w.length;
            if (i + len <= L && target.startsWith(w, i))
                dp[i + len] = Math.min(dp[i + len], dp[i] + c);
        }
    }
    return dp[L] === INF ? -1 : dp[L];
};
